// Paste as the Source expression's backtick string, followed by ;0.
// Fresh bindings: Float 01=gain, Color 01=tint RGB, Float 02=tint alpha,
// Angle 01=angle. The angle deliberately tests defaults without changing RGB.
// @param gain label:"Fresh Gain" min:0 max:2 default:0.25
// @param tint label:"Fresh Color" hint:color default:0.25,0.6,1,0.4
// @param angle label:"Fresh Angle" hint:angle default:12.34567
struct FxUniforms {
    u_resolution: vec2<f32>,
    u_time: f32,
    u_frame: f32,
    gain: f32,
    tint: vec4<f32>,
    angle: f32,
}
@group(0) @binding(2) var<uniform> fx: FxUniforms;
@fragment
fn main() -> @location(0) vec4<f32> {
    return vec4<f32>(fx.tint.rgb * fx.gain, fx.tint.a);
}
